/**
 * @ingroup iface_xx_zone_v1
 * @struct xx_zone_v1_interface
 */
struct xx_zone_v1_interface {
	/**
	 * destroy the xx_zone object
	 *
	 * Using this request a client can tell the compositor that it is
	 * not going to use the 'xx_zone' object anymore. The zone itself
	 * must only be destroyed if no other client is currently
	 * referencing it, so this request may only destroy the object
	 * reference owned by the client.
	 */
	void (*destroy)(struct wl_client *client,
			struct wl_resource *resource);
	/**
	 * associate an item with this zone
	 *
	 * Make 'item' a member of this zone. This state is
	 * double-buffered and is applied on the next 'wl_surface.commit'
	 * of the surface represented by 'item'.
	 *
	 * This request associates an item with this zone. If this request
	 * is called on an item that already has a zone association with a
	 * different zone, the item must leave its old zone (with
	 * 'item_left' being emitted on its old zone) and will instead be
	 * associated with this zone.
	 *
	 * Upon receiving this request and if the target zone is allowed
	 * for 'item', a compositor must emit 'item_entered' to confirm the
	 * zone association. It must even emit this event if the item was
	 * already associated with this zone before.
	 *
	 * The compositor must move the surface represented by 'item' into
	 * the boundary of this zone upon receiving this request and
	 * accepting it (either by extending the zone size, or by moving
	 * the item surface).
	 *
	 * If the compositor does not allow the item to switch zone
	 * associations, and wants it to remain in its previous zone, it
	 * must emit 'item_blocked' instead. Compositors might want to
	 * prevent zone associations if they perform specialized window
	 * management (e.g. autotiling) that would make clients moving
	 * items between certain zones undesirable.
	 *
	 * Once the 'item' is added to its zone, the compositor must first
	 * send a 'frame_extents' event on the item, followed by an initial
	 * 'position' event with the item's current position. The
	 * compositor must then send 'position' events when the position of
	 * the item in its zone is changed, for as long as the item is
	 * associated with a zone.
	 *
	 * If the zone is invalid, an 'invalid' error must be raised and
	 * the item must not be associated with the invalid zone. If the
	 * referenced item is inert (its underlying surface has been
	 * destroyed), the request must be silently ignored.
	 * @param item the zone item
	 */
	void (*add_item)(struct wl_client *client,
			 struct wl_resource *resource,
			 struct wl_resource *item);
	/**
	 * disassociate an item from this zone
	 *
	 * Remove 'item' as a member of this zone. This state is
	 * double-buffered and is applied on the next 'wl_surface.commit'
	 * of the surface represented by 'item'.
	 *
	 * This request removes the item from this zone explicitly, making
	 * the client unable to retrieve coordinates again.
	 *
	 * Upon receiving this request, the compositor should not change
	 * the item surface position on screen, and must emit 'item_left'
	 * to confirm the item's removal. It must even emit this event if
	 * the item was never associated with this zone.
	 *
	 * If the referenced item is inert (its underlying surface has been
	 * destroyed), the request must be silently ignored.
	 * @param item the zone item
	 */
	void (*remove_item)(struct wl_client *client,
			    struct wl_resource *resource,
			    struct wl_resource *item);
};

